/**
 * Returns a 12-hour time in H:MM AM/PM format from an ISO-like input.
 */
export function formatTimeHms(value: string | null | undefined): string {
  if (!value) {
    return "12:00 AM";
  }

  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return "12:00 AM";
  }

  const rawHours = parsed.getHours();
  const minutes = String(parsed.getMinutes()).padStart(2, "0");
  const meridiem = rawHours >= 12 ? "PM" : "AM";
  const hours = rawHours % 12 === 0 ? 12 : rawHours % 12;
  return `${hours}:${minutes} ${meridiem}`;
}

