/**
 * Returns a readable local date-time in YYYY-MM-DD H:MM AM/PM format.
 */
export function formatDateTimeHms(value: string | null | undefined): string {
  if (!value) {
    return "not set";
  }

  if (/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return value;
  }

  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return value;
  }

  const year = parsed.getFullYear();
  const month = String(parsed.getMonth() + 1).padStart(2, "0");
  const day = String(parsed.getDate()).padStart(2, "0");
  return `${year}-${month}-${day} ${formatTimeHms(value)}`;
}